import React, { useState } from 'react';
// استيراد المكونات
import Sidebar from './components/Sidebar';
// استيراد صفحات الطالب (تأكد من صحة مسارات الملفات لديك)
import StudentDashboard from './pages/StudentDashboard';
import StudentOffers from './pages/StudentOffers';
import MyApplications from './pages/MyApplications';
import StudentProfile from './pages/StudentProfile';
import StudentSettings from './pages/StudentSettings';

function App() {
  // الحالة المسؤولة عن تحديد الصفحة المعروضة حالياً
  const [activeTab, setActiveTab] = useState('dashboard');

  // دالة لاختيار الصفحة بناءً على القيمة في activeTab
  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <StudentDashboard />;
      case 'offers':
        return <StudentOffers />;
      case 'applications':
        return <MyApplications />;
      case 'profile':
        return <StudentProfile />;
      case 'settings':
        return <StudentSettings />;
      default:
        return <StudentDashboard />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex" dir="rtl">
      {/* 1. المحتوى الرئيسي (Main Content) */}
      <main className="flex-1 mr-64 p-4">
        {/* سيتم تبديل هذا الجزء ديناميكياً */}
        <div className="max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>

      {/* 2. الشريط الجانبي (Sidebar) */}
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
    </div>
  );
}

export default App;
